package com.infernodude777.endesium.resonance;

/**
 * Classifies resonance sources by their nature and detection range.
 * The client never sees this enum directly; it influences the
 * qualitative Lens description only.
 */
public enum ResonanceType {
    /** A dormant relic waiting to be activated. */
    DORMANT_RELIC,
    /** An activated mechanism emitting a steady pulse. */
    ACTIVE_MECHANISM,
    /** A stronger relic felt from much farther away. */
    STRONG_RELIC,
    /** Reserved for the Shattered Spire landmark. */
    SPIRE_CORE,
    /** The Resonant Archive core after the Dragon is defeated. */
    AWAKENED_ARCHIVE,
    /** Reserved for future Void Stalker traces; not registered yet. */
    CREATURE_TRACE
}

package com.infernodude777.endesium.resonance;

import com.infernodude777.endesium.Endesium;
import com.mojang.serialization.Codec;
import net.fabricmc.fabric.api.attachment.v1.AttachmentRegistry;
import net.fabricmc.fabric.api.attachment.v1.AttachmentType;
import net.minecraft.server.level.ServerPlayer;

/**
 * Persistent player attachment tracking accumulated resonance.
 * Resonance is a soft progression currency that gates later recipes.
 */
public final class Resonance {
    private static final int MAX_RESONANCE = 100;

    public static final AttachmentType<Integer> LEVEL = AttachmentRegistry.createPersistent(
            Endesium.id("resonance"),
            Codec.INT
    );

    private Resonance() { }

    /** Returns the player's current resonance level (0-100). */
    public static int get(ServerPlayer player) {
        return player.getAttachedOrElse(LEVEL, 0);
    }

    /**
     * Adds resonance for this player, clamped to [0, MAX_RESONANCE].
     * @return the new resonance level after the grant.
     */
    public static int add(ServerPlayer player, int amount) {
        int next = Math.clamp(get(player) + amount, 0, MAX_RESONANCE);
        player.setAttached(LEVEL, next);
        return next;
    }
}

package com.infernodude777.endesium.resonance;

import net.minecraft.core.BlockPos;

/**
 * Immutable position + mutable signal data for a single resonance source.
 * Sources self-register through block entities and are pruned when their
 * chunk unloads.
 */
public final class ResonanceSource {
    private final BlockPos position;
    private ResonanceType type;
    private int detectionRadius;
    private float strength;
    private boolean active;

    public ResonanceSource(BlockPos position, ResonanceType type,
                           int detectionRadius, float strength, boolean active) {
        this.position = position.immutable();
        update(type, detectionRadius, strength, active);
    }

    public BlockPos position() {
        return position;
    }

    public ResonanceType type() {
        return type;
    }

    public int detectionRadius() {
        return detectionRadius;
    }

    public float strength() {
        return strength;
    }

    public boolean active() {
        return active;
    }

    /**
     * Updates the mutable fields of this source in-place.
     * Radius and strength are clamped to safe ranges.
     */
    public void update(ResonanceType type, int detectionRadius, float strength, boolean active) {
        this.type = type;
        this.detectionRadius = Math.clamp(detectionRadius, 1, 96);
        this.strength = Math.clamp(strength, 0.0F, 1.35F);
        this.active = active;
    }

    public void setActive(boolean active) {
        this.active = active;
    }
}

