package com.infernodude777.endesium.block;

import com.mojang.serialization.MapCodec;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.IntegerProperty;

/**
 * A wall/floor tile carved with one of the recurring Endesium motifs.
 * The symbol property is set at generation time; players gradually learn
 * that the ring, the spire, and the eye always appear together near
 * places that matter.
 */
public class InscribedSlateBlock extends Block {
    public static final IntegerProperty SYMBOL = IntegerProperty.create("symbol", 0, 3);
    public static final int SYMBOL_RING = 0;
    public static final int SYMBOL_SPIRE = 1;
    public static final int SYMBOL_EYE = 2;
    public static final int SYMBOL_PLAIN = 3;

    private static final MapCodec<InscribedSlateBlock> CODEC = simpleCodec(InscribedSlateBlock::new);

    public InscribedSlateBlock(BlockBehaviour.Properties properties) {
        super(properties);
        registerDefaultState(stateDefinition.any().setValue(SYMBOL, SYMBOL_RING));
    }

    @Override
    protected MapCodec<? extends Block> codec() {
        return CODEC;
    }

    @Override
    protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
        builder.add(SYMBOL);
    }
}

package com.infernodude777.endesium.block;

import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.LiquidBlock;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;

/**
 * A thin, temporary crust formed over lava by Ashwalker Boots.
 * The flow level is copied into the crust state and restored when the
 * scheduled tick fires, preventing walking boots from turning every
 * flowing lava stream into a new source block.
 */
public final class AshenCrustBlock extends Block {
    private static final int LIFETIME_TICKS = 60;

    public AshenCrustBlock(BlockBehaviour.Properties properties) {
        super(properties);
        registerDefaultState(stateDefinition.any().setValue(BlockStateProperties.LEVEL, 0));
    }

    @Override
    protected void createBlockStateDefinition(
            net.minecraft.world.level.block.state.StateDefinition.Builder<Block, BlockState> builder) {
        builder.add(BlockStateProperties.LEVEL);
    }

    @Override
    protected void onPlace(BlockState state, Level level, BlockPos pos,
                           BlockState oldState, boolean movedByPiston) {
        level.scheduleTick(pos, this, LIFETIME_TICKS + level.getRandom().nextInt(40));
    }

    @Override
    protected void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
        int lavaLevel = state.getValue(BlockStateProperties.LEVEL);
        level.setBlock(pos, Blocks.LAVA.defaultBlockState().setValue(LiquidBlock.LEVEL, lavaLevel), 3);
    }
}

package com.infernodude777.endesium.resonance;

import com.infernodude777.endesium.Endesium;
import net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.LivingEntity;

/**
 * Wires the persistent {@link Resonance} attachment into gameplay.
 * Grants resonance when a player defeats an Endesium mob and emits a
 * short chat notice when the player crosses a resonance tier.
 */
public final class ResonanceSystem {
    private static final int[] TIER_THRESHOLDS = { 0, 20, 40, 60, 80, 100 };
    private static final String[] TIER_NAMES = {
            "Still", "Attuned", "Awakened", "Resonant", "Harmonized", "Ascendant"
    };

    private ResonanceSystem() { }

    public static void register() {
        ServerLivingEntityEvents.AFTER_DEATH.register(ResonanceSystem::onMobDeath);
        Endesium.LOGGER.info("Endesium resonance system registered (kills grant resonance)");
    }

    private static void onMobDeath(LivingEntity entity, DamageSource source) {
        if (entity.level().isClientSide) return;
        if (!isEndesiumMob(entity)) return;
        if (!(source.getEntity() instanceof ServerPlayer player)) return;

        int tierBefore = tierFor(Resonance.get(player));
        int next = Resonance.add(player, grantFor(entity));
        int tierAfter = tierFor(next);

        if (tierAfter > tierBefore) {
            player.sendSystemMessage(Component.literal(
                    "Resonance rises: you are now " + TIER_NAMES[tierAfter]
                            + " (" + next + "/100)."));
        }
    }

    /** Larger, rarer creatures carry more resonance. */
    private static int grantFor(LivingEntity entity) {
        switch (entity.getType().getDescriptionId()) {
            case "entity.endesium.void_stalker":
            case "entity.endesium.ash_wraith":
                return 4;
            case "entity.endesium.chorus_stalker":
            case "entity.endesium.nullwalker":
                return 3;
            default:
                return 2;
        }
    }

    private static boolean isEndesiumMob(LivingEntity entity) {
        ResourceLocation id = entity.getType().builtInRegistryHolder().key().location();
        return "endesium".equals(id.getNamespace());
    }

    public static int tierFor(int resonance) {
        int tier = 0;
        for (int i = 0; i < TIER_THRESHOLDS.length; i++) {
            if (resonance >= TIER_THRESHOLDS[i]) {
                tier = i;
            }
        }
        return tier;
    }

    public static String tierName(int resonance) {
        return TIER_NAMES[tierFor(resonance)];
    }
}

package com.infernodude777.endesium.dragon;

import com.infernodude777.endesium.registry.ModItems;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.RandomSource;
import net.minecraft.world.entity.boss.enderdragon.EnderDragon;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;

/**
 * Code-driven Dragon material drops. The first kill guarantees the Resonant
 * Elytra bundle (4 Resonant Dragon Scales + supporting materials); later
 * kills grant reduced quantities and rolls. Looting never applies: the drops
 * are granted on the death hook, not through the vanilla loot table.
 */
public final class DragonLoot {
    private DragonLoot() { }

    /**
     * Grants curated drops based on whether this is the first dragon kill.
     * First kills are deterministic; subsequent kills are probabilistic.
     */
    public static void grantDrops(EnderDragon dragon, ServerLevel level, boolean firstKill) {
        RandomSource random = level.random;

        if (firstKill) {
            drop(dragon, ModItems.RESONANT_DRAGON_SCALE, 4);
            drop(dragon, ModItems.DRAGONBONE, 2 + random.nextInt(2));
            drop(dragon, ModItems.ENDER_ESSENCE, 2);
            drop(dragon, ModItems.ECHO_SHARD, 1);
            drop(dragon, ModItems.PROGRESSION_GUIDE, 1);
            drop(dragon, ModItems.ARCHIVE_FRAGMENT, 1);
        } else {
            if (random.nextFloat() < 0.67F) {
                drop(dragon, ModItems.RESONANT_DRAGON_SCALE, 1 + random.nextInt(2));
            }
            drop(dragon, ModItems.DRAGONBONE, 1 + random.nextInt(2));
            if (random.nextFloat() < 0.6F) {
                drop(dragon, ModItems.ENDER_ESSENCE, 1);
            }
        }

        roll(dragon, random, ModItems.DRAGON_FANG, firstKill ? 0.25F : 0.12F);
        roll(dragon, random, ModItems.VOID_PEARL, firstKill ? 0.20F : 0.10F);
        roll(dragon, random, ModItems.ABYSSAL_THREAD, firstKill ? 0.30F : 0.15F);
        roll(dragon, random, ModItems.RESONANCE_CORE, firstKill ? 0.20F : 0.10F);
        if (random.nextFloat() < (firstKill ? 0.10F : 0.04F)) {
            drop(dragon, ModItems.DRAGON_HEART, 1);
        }
    }

    private static void roll(EnderDragon dragon, RandomSource random, Item item, float chance) {
        if (random.nextFloat() < chance) {
            drop(dragon, item, 1);
        }
    }

    private static void drop(EnderDragon dragon, Item item, int count) {
        dragon.spawnAtLocation(new ItemStack(item, count));
    }
}

package com.infernodude777.endesium.dragon;

import com.infernodude777.endesium.registry.ModItems;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;

/**
 * Enhanced hoard dropped when the Dragon falls. The assault layer calls
 * this once on death to spawn a curated pile of dragon materials at the
 * death site. Vanilla already pays experience; this is the material
 * payoff that makes each kill worth looting.
 */
public final class DragonRewards {
    private DragonRewards() { }

    public static void dropEnhancedLoot(ServerLevel level, BlockPos pos) {
        BlockPos at = pos == null ? new BlockPos(0, 64, 0) : pos;
        double x = at.getX() + 0.5D;
        double y = at.getY() + 1.0D;
        double z = at.getZ() + 0.5D;

        drop(level, x, y, z, ModItems.DRAGON_HEART, 1);
        drop(level, x, y, z, ModItems.DRAGON_FANG, 3);
        drop(level, x, y, z, ModItems.DRAGONBONE, 8);
        drop(level, x, y, z, ModItems.RESONANT_DRAGON_SCALE, 2);
        level.playSound(null, at, SoundEvents.ENDER_DRAGON_DEATH, SoundSource.AMBIENT, 1.0F, 0.8F);
    }

    private static void drop(ServerLevel level, double x, double y, double z,
                            Item item, int count) {
        for (int i = 0; i < count; i++) {
            ItemEntity entity = new ItemEntity(level, x, y, z, new ItemStack(item));
            entity.setPickUpDelay(20);
            level.addFreshEntity(entity);
        }
    }
}

package com.infernodude777.endesium.dragon;

import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.datafix.DataFixTypes;
import net.minecraft.world.level.saveddata.SavedData;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * Persistent, server-side Sonic Boom cooldowns keyed by player UUID.
 * Because the state lives in world data rather than on the item or the
 * player, the cooldown cannot be bypassed by swapping items, reconnecting,
 * or dying. Old entries are pruned so the map stays bounded.
 */
public final class SonicCooldownData extends SavedData {
    public static final String FILE_NAME = "endesium_sonic_cooldowns";

    private static final SavedData.Factory<SonicCooldownData> FACTORY =
            new SavedData.Factory<>(SonicCooldownData::new, SonicCooldownData::load,
                    DataFixTypes.SAVED_DATA_COMMAND_STORAGE);

    private final Map<UUID, Long> readyAtGameTime = new HashMap<>();

    public SonicCooldownData() { }

    public static SonicCooldownData load(CompoundTag tag, HolderLookup.Provider registries) {
        SonicCooldownData data = new SonicCooldownData();
        ListTag list = tag.getList("Cooldowns", Tag.TAG_COMPOUND);
        for (int i = 0; i < list.size(); i++) {
            CompoundTag entry = list.getCompound(i);
            try {
                data.readyAtGameTime.put(entry.getUUID("U"), entry.getLong("T"));
            } catch (IllegalArgumentException ignored) {
                // Malformed or stale entry; skip.
            }
        }
        return data;
    }

    @Override
    public CompoundTag save(CompoundTag tag, HolderLookup.Provider registries) {
        ListTag list = new ListTag();
        for (Map.Entry<UUID, Long> entry : readyAtGameTime.entrySet()) {
            CompoundTag item = new CompoundTag();
            item.putUUID("U", entry.getKey());
            item.putLong("T", entry.getValue());
            list.add(item);
        }
        tag.put("Cooldowns", list);
        return tag;
    }

    /** Returns true if the player is still on cooldown. */
    public boolean onCooldown(UUID player, long gameTime) {
        Long readyAt = readyAtGameTime.get(player);
        return readyAt != null && readyAt > gameTime;
    }

    /** Sets the cooldown end time for a player and prunes stale entries. */
    public void setCooldown(UUID player, long readyGameTime) {
        readyAtGameTime.put(player, readyGameTime);
        if (readyAtGameTime.size() > 64) {
            readyAtGameTime.entrySet().removeIf(
                    entry -> entry.getValue() <= readyGameTime - 3600L);
        }
        setDirty();
    }

    public static SonicCooldownData get(MinecraftServer server) {
        return server.overworld().getDataStorage()
                .computeIfAbsent(FACTORY, FILE_NAME);
    }
}

package com.infernodude777.endesium.dragon;

import com.infernodude777.endesium.particle.ModParticles;
import com.infernodude777.endesium.registry.ModItems;
import com.infernodude777.endesium.registry.ModSounds;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import java.util.HashSet;
import java.util.Set;

/**
 * The Resonant Elytra's signature ability. Fires a straight 40-block
 * resonance ray: 8 damage through the sonic-boom damage source (ignores
 * armor), strong knockback, and a distinctive sound. The 15-second cooldown
 * is persisted in {@link SonicCooldownData}.
 */
public final class SonicBoomHandler {
    private static final double RANGE = 40.0D;
    private static final float DAMAGE = 8.0F;
    private static final int COOLDOWN_TICKS = 300;

    private SonicBoomHandler() { }

    public static void fire(ServerPlayer player) {
        if (!player.isAlive() || player.isSpectator()) return;
        ServerLevel level = player.serverLevel();
        long gameTime = level.getGameTime();
        SonicCooldownData cooldowns = SonicCooldownData.get(player.server);
        if (cooldowns.onCooldown(player.getUUID(), gameTime)) return;
        if (!player.getItemBySlot(EquipmentSlot.CHEST).is(ModItems.RESONANT_WINGS)) return;

        cooldowns.setCooldown(player.getUUID(), gameTime + COOLDOWN_TICKS);
        player.getItemBySlot(EquipmentSlot.CHEST).hurtAndBreak(1, player, EquipmentSlot.CHEST);

        Vec3 eye = player.getEyePosition();
        Vec3 look = player.getLookAngle();
        Set<LivingEntity> victims = new HashSet<>();

        for (double distance = 1.0D; distance <= RANGE; distance += 1.0D) {
            Vec3 point = eye.add(look.scale(distance));
            if (distance % 3 == 0) {
                level.sendParticles(ParticleTypes.SONIC_BOOM, point.x, point.y, point.z,
                        1, 0.0D, 0.0D, 0.0D, 0.0D);
            } else if (distance % 2 == 0) {
                level.sendParticles(ModParticles.RESONANCE_BEAM, point.x, point.y, point.z,
                        1, 0.0D, 0.0D, 0.0D, 0.0D);
            }
            for (LivingEntity entity : level.getEntitiesOfClass(LivingEntity.class,
                    new AABB(point, point).inflate(1.75D),
                    entity -> entity != player && entity.isAlive())) {
                victims.add(entity);
            }
        }

        for (LivingEntity entity : victims) {
            if (entity.isDeadOrDying()) continue;
            entity.hurt(level.damageSources().sonicBoom(player), DAMAGE);
            Vec3 away = entity.position().subtract(eye).normalize();
            entity.knockback(1.4D, away.x, away.z);
        }

        level.playSound(null, player.blockPosition(), ModSounds.SONIC_BOOM,
                SoundSource.PLAYERS, 1.2F, 1.0F);
        level.sendParticles(ParticleTypes.SONIC_BOOM,
                eye.x + look.x * 2.0D, eye.y + look.y * 2.0D,
                eye.z + look.z * 2.0D, 6, 0.4D, 0.4D, 0.4D, 0.02D);
    }
}

package com.infernodude777.endesium.dragon;

import com.infernodude777.endesium.Endesium;
import com.infernodude777.endesium.particle.ModParticles;
import com.infernodude777.endesium.registry.ModItems;
import com.infernodude777.endesium.resonance.ResonanceManager;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.level.Level;

/**
 * Server-side passive abilities of the Resonant Elytra:
 * • Raised step height (STEP_HEIGHT attribute to 1.0).
 * • Resonant Plating — +4 armor points while worn.
 * • Resonant Vitality — three extra hearts while worn.
 * • Resonance Sense — faint motes when a meaningful source is near.
 */
public final class ResonantWingsPassives {
    private static final ResourceLocation STEP_MODIFIER_ID = Endesium.id("resonant_step");
    private static final AttributeModifier STEP_MODIFIER = new AttributeModifier(
            STEP_MODIFIER_ID, 0.4D, AttributeModifier.Operation.ADD_VALUE);

    private static final ResourceLocation PLATING_MODIFIER_ID = Endesium.id("resonant_plating");
    private static final AttributeModifier PLATING_MODIFIER = new AttributeModifier(
            PLATING_MODIFIER_ID, 4.0D, AttributeModifier.Operation.ADD_VALUE);

    private static final ResourceLocation VITALITY_MODIFIER_ID = Endesium.id("resonant_vitality");
    private static final AttributeModifier VITALITY_MODIFIER = new AttributeModifier(
            VITALITY_MODIFIER_ID, 6.0D, AttributeModifier.Operation.ADD_VALUE);

    private ResonantWingsPassives() { }

    public static void tick(ServerPlayer player, int globalTick) {
        boolean wearing = player.getItemBySlot(EquipmentSlot.CHEST).is(ModItems.RESONANT_WINGS);

        applyWhileWorn(player.getAttribute(Attributes.STEP_HEIGHT), wearing,
                STEP_MODIFIER_ID, STEP_MODIFIER);
        applyWhileWorn(player.getAttribute(Attributes.ARMOR), wearing,
                PLATING_MODIFIER_ID, PLATING_MODIFIER);
        applyWhileWorn(player.getAttribute(Attributes.MAX_HEALTH), wearing,
                VITALITY_MODIFIER_ID, VITALITY_MODIFIER);

        if (!wearing || globalTick % 100 != 0) return;
        if (player.level().dimension() != Level.END) return;

        ResonanceManager.Signal signal = ResonanceManager.get(player.serverLevel()).sample(player);
        if (signal.band() != ResonanceManager.Band.NONE && signal.strength() > 0.25F) {
            player.serverLevel().sendParticles(ModParticles.RESONANCE_PULSE,
                    player.getX() + (player.getRandom().nextDouble() - 0.5D) * 1.6D,
                    player.getY(0.8D),
                    player.getZ() + (player.getRandom().nextDouble() - 0.5D) * 1.6D,
                    2, 0.2D, 0.2D, 0.2D, 0.01D);
        }
    }

    /** Adds the modifier while worn, removes it otherwise; null-safe. */
    private static void applyWhileWorn(AttributeInstance attribute, boolean wearing,
                                      ResourceLocation id, AttributeModifier modifier) {
        if (attribute == null) return;
        if (wearing) {
            if (!attribute.hasModifier(id)) {
                attribute.addTransientModifier(modifier);
            }
        } else if (attribute.hasModifier(id)) {
            attribute.removeModifier(id);
        }
    }
}

