import software.bernie.geckolib.animatable.GeoEntity;
import software.bernie.geckolib.animatable.instance.AnimatableInstanceCache;
import software.bernie.geckolib.animation.AnimationController;
import software.bernie.geckolib.animation.AnimationState;
import software.bernie.geckolib.animation.AnimatableManager;
import software.bernie.geckolib.animation.PlayState;
import software.bernie.geckolib.animation.RawAnimation;
import software.bernie.geckolib.util.GeckoLibUtil;

/**
 * The End Wastes sentinel. Maintains distance, observes, and strikes
 * with telegraphed lunges. Enrages below half health for a speed boost.
 */
public class ProductionVoidStalkerEntity extends Monster implements GeoEntity {
    private static final double DETECTION_RANGE_SQR = 32.0D * 32.0D;
    private static final double PREFERRED_MIN_SQR = 6.0D * 6.0D;
    private static final double PREFERRED_MAX_SQR = 10.0D * 10.0D;
    private static final double ATTACK_RANGE_SQR = 2.6D * 2.6D;
    private static final int ATTACK_COOLDOWN = 24;
    private static final int REPOSITION_COOLDOWN = 160;
    private static final int REPOSITION_FAIL_COOLDOWN = 80;
    private static final int SEARCH_TIMEOUT = 100;
    private static final int AWARE_TICKS = 15;
    private static final EntityDataAccessor<Integer> DATA_STATE = SynchedEntityData.defineId(
            ProductionVoidStalkerEntity.class, EntityDataSerializers.INT);

    private static final RawAnimation IDLE = RawAnimation.begin().thenLoop("animation.void_stalker.idle_listen");
    private static final RawAnimation OBSERVE_ANIM = RawAnimation.begin().thenLoop("animation.void_stalker.observe");
    private static final RawAnimation WALK = RawAnimation.begin().thenLoop("animation.void_stalker.walk");
    private static final RawAnimation RUN = RawAnimation.begin().thenLoop("animation.void_stalker.run");
    private static final RawAnimation ATTACK = RawAnimation.begin().thenPlay("animation.void_stalker.attack_anticipation").thenPlay("animation.void_stalker.attack_impact").thenPlay("animation.void_stalker.attack_recovery");
    private static final RawAnimation HURT_ANIM = RawAnimation.begin().thenPlay("animation.void_stalker.hurt");
    private static final RawAnimation REPOSITION_ANIM = RawAnimation.begin().thenPlay("animation.void_stalker.reposition");
    private static final RawAnimation DEATH = RawAnimation.begin().thenPlay("animation.void_stalker.death");

    private final AnimatableInstanceCache animationCache = GeckoLibUtil.createInstanceCache(this);
    private State state = State.IDLE;
    private int stateTicks;
    private int attackCooldown;
    private int repositionCooldown;
    private BlockPos lastKnownPlayerPos;
    private int searchTicks;
    private boolean enraged;

    public ProductionVoidStalkerEntity(EntityType<? extends ProductionVoidStalkerEntity> type, Level level) {
        super(type, level);
    }

    public static AttributeSupplier.Builder createAttributes() {
        return Mob.createMobAttributes()
                .add(Attributes.MAX_HEALTH, 24.0D)
                .add(Attributes.MOVEMENT_SPEED, 0.28D)
                .add(Attributes.ATTACK_DAMAGE, 4.0D)
                .add(Attributes.FOLLOW_RANGE, 32.0D)
                .add(Attributes.KNOCKBACK_RESISTANCE, 0.35D);
    }

    @Override
    protected void registerGoals() {
        goalSelector.addGoal(0, new FloatGoal(this));
        goalSelector.addGoal(5, new RandomStrollGoal(this, 0.7D));
        goalSelector.addGoal(6, new LookAtPlayerGoal(this, Player.class, 14.0F));
        goalSelector.addGoal(7, new RandomLookAroundGoal(this));
        targetSelector.addGoal(1, new HurtByTargetGoal(this));
        targetSelector.addGoal(2, new NearestAttackableTargetGoal<>(this, Player.class, true));
    }

    @Override
    protected void defineSynchedData(SynchedEntityData.Builder builder) {
        super.defineSynchedData(builder);
        builder.define(DATA_STATE, State.IDLE.ordinal());
    }

    @Override
    public void tick() {
        super.tick();
        if (!level().isClientSide()) updateBehavior();
    }

    private void updateBehavior() {
        tickCombatPhase();
        if (attackCooldown > 0) attackCooldown--;
        if (repositionCooldown > 0) repositionCooldown--;
        LivingEntity target = getTarget();
        if (target != null && target.isAlive()) {
            lastKnownPlayerPos = target.blockPosition();
            if (state != State.SEARCH) searchTicks = 0;
        }
        if (target == null || !target.isAlive()) {
            if (state == State.SEARCH && lastKnownPlayerPos != null) {
                if (searchTicks++ >= SEARCH_TIMEOUT) {
                    lastKnownPlayerPos = null;
                    setTarget(null);
                    enterState(State.IDLE);
                    return;
                }
                if (navigation.isDone()) {
                    navigation.moveTo(lastKnownPlayerPos.getX() + 0.5D, lastKnownPlayerPos.getY(), lastKnownPlayerPos.getZ() + 0.5D, 1.0D);
                }
                return;
            }
            lastKnownPlayerPos = null;
            enterState(State.IDLE);
            return;
        }
        stateTicks++;
        lookAt(target, 30.0F, 30.0F);
        double distance = distanceToSqr(target);
        if (distance > DETECTION_RANGE_SQR) {
            setTarget(null);
            lastKnownPlayerPos = null;
            enterState(State.IDLE);
            return;
        }
        boolean los = hasLineOfSight(target);
        switch (state) {
            case IDLE -> {
                if (distance <= DETECTION_RANGE_SQR) enterState(State.AWARE);
            }
            case AWARE -> {
                if (stateTicks >= AWARE_TICKS) enterState(los ? State.OBSERVE : State.SEARCH);
            }
            case SEARCH -> {
                if (los) enterState(State.OBSERVE);
                else if (searchTicks++ >= SEARCH_TIMEOUT) {
                    lastKnownPlayerPos = null;
                    setTarget(null);
                    enterState(State.IDLE);
                }
            }
            case OBSERVE -> {
                if (!los && stateTicks > 60) { enterState(State.SEARCH); return; }
                if (distance > PREFERRED_MAX_SQR) { enterState(State.POSITION); return; }
                if (distance <= ATTACK_RANGE_SQR && attackCooldown == 0) {
                    attackCooldown = ATTACK_COOLDOWN;
                    enterState(State.ATTACK_PREP);
                    return;
                }
                if (distance < 5.0D * 5.0D && stateTicks > 40 && repositionCooldown == 0) {
                    enterState(State.REPOSITION);
                    return;
                }
                if (getHealth() < getMaxHealth() * 0.3F) { enterState(State.RETREAT); return; }
                navigation.stop();
            }
            case POSITION -> {
                if (!los && stateTicks > 60) { enterState(State.SEARCH); return; }
                if (distance <= PREFERRED_MAX_SQR && distance >= PREFERRED_MIN_SQR) enterState(State.OBSERVE);
                else if (distance > PREFERRED_MAX_SQR) navigation.moveTo(target, 1.2D);
                else if (repositionCooldown == 0 && stateTicks > 60) enterState(State.REPOSITION);
            }
            case ATTACK_PREP -> {
                navigation.stop();
                if (!los || distance > 3.5D * 3.5D) { enterState(State.POSITION); return; }
                if (stateTicks == 1 && level() instanceof ServerLevel serverLevel) {
                    serverLevel.sendParticles(ModParticles.RESONANCE_ACTIVE, getX(), getEyeY(), getZ(), 5, 0.12D, 0.12D, 0.12D, 0.01D);
                }
                if (stateTicks == 9) {
                    target.hurt(damageSources().mobAttack(this), (float) getAttributeValue(Attributes.ATTACK_DAMAGE));
                    playSound(ModSounds.VOID_STALKER_ATTACK, 1.0F, 1.0F);
                }
                if (stateTicks >= 14) enterState(State.RECOVER);
            }
            case RECOVER -> {
                navigation.stop();
                if (stateTicks >= 10) enterState(getHealth() < getMaxHealth() * 0.3F ? State.RETREAT : State.OBSERVE);
            }
            case REPOSITION -> {
                navigation.stop();
                if (stateTicks >= 12) reposition(target);
            }
            case RETREAT -> {
                if (distance >= 12.0D * 12.0D) { enterState(State.OBSERVE); return; }
                if (!los && stateTicks > 60) { enterState(State.SEARCH); return; }
                Vec3 away = position().subtract(target.position()).normalize();
                Vec3 retreatDestination = position().add(away.scale(14.0D));
                navigation.moveTo(retreatDestination.x, retreatDestination.y, retreatDestination.z, 1.1D);
            }
            case HURT -> {
                navigation.stop();
                if (stateTicks >= 6) enterState(State.OBSERVE);
            }
        }
    }

    private void tickCombatPhase() {
        boolean shouldEnrage = getHealth() < getMaxHealth() * 0.5F;
        if (shouldEnrage && !enraged) {
            enraged = true;
            getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue() + 0.10D);
            if (level() instanceof ServerLevel serverLevel) {
                serverLevel.sendParticles(ModParticles.VOID_STALKER_TRACE, getX(), getY() + 1.0D, getZ(), 16, 0.4D, 0.6D, 0.4D, 0.03D);
                playSound(ModSounds.VOID_STALKER_ATTACK, 1.0F, 0.7F);
            }
        } else if (!shouldEnrage && enraged) {
            enraged = false;
            getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue() - 0.10D);
        }
    }

    private void reposition(LivingEntity target) {
        Vec3 away = position().subtract(target.position()).normalize();
        Vec3 side = new Vec3(-away.z, 0.0D, away.x).normalize();
        if (side.lengthSqr() < 0.1D) side = new Vec3(1.0D, 0.0D, 0.0D);
        if (random.nextBoolean()) side = side.scale(-1.0D);
        double repositionDistance = 8.0D + random.nextInt(7);
        Vec3 destination = target.position().add(side.scale(repositionDistance));
        BlockPos ground = BlockPos.containing(destination).below();
        boolean valid = level().getBlockState(ground).isSolidRender(level(), ground)
                && level().noCollision(this, getBoundingBox().move(destination.subtract(position())))
                && !level().getBlockState(BlockPos.containing(destination)).isSolidRender(level(), BlockPos.containing(destination));
        if (valid) {
            teleportTo(destination.x, ground.getY() + 1.0D, destination.z);
            if (level() instanceof ServerLevel serverLevel) {
                serverLevel.sendParticles(ModParticles.VOID_STALKER_TRACE, getX(), getY(), getZ(), 8, 0.3D, 0.3D, 0.3D, 0.02D);
            }
            playSound(ModSounds.VOID_STALKER_REPOSITION, 0.8F, 1.0F);
            repositionCooldown = REPOSITION_COOLDOWN;
        } else {
            repositionCooldown = REPOSITION_FAIL_COOLDOWN;
        }
        enterState(State.OBSERVE);
    }

    @Override
    public boolean hurt(DamageSource source, float amount) {
        boolean wasHurt = super.hurt(source, amount);
        if (wasHurt && isAlive() && state != State.ATTACK_PREP && state != State.REPOSITION) {
            enterState(State.HURT);
        }
        return wasHurt;
    }

    @Override
    protected int getBaseExperienceReward() {
        return 5;
    }

    @Override
    protected ResourceKey<LootTable> getDefaultLootTable() {
        return ResourceKey.create(Registries.LOOT_TABLE, com.infernodude777.endesium.Endesium.id("entities/void_stalker"));
    }

    @Override
    protected SoundEvent getAmbientSound() {
        return ModSounds.VOID_STALKER_IDLE;
    }

    @Override
    public int getAmbientSoundInterval() {
        return 300 + random.nextInt(200);
    }

    @Override
    protected float getSoundVolume() {
        return 0.6F;
    }

    @Override
    protected SoundEvent getHurtSound(DamageSource damageSource) {
        return ModSounds.VOID_STALKER_HURT;
    }

    @Override
    protected SoundEvent getDeathSound() {
        return ModSounds.VOID_STALKER_DEATH;
    }

    private void enterState(State next) {
        if (state == next) return;
        state = next;
        stateTicks = 0;
        entityData.set(DATA_STATE, next.ordinal());
    }

    public State state() {
        int ordinal = entityData.get(DATA_STATE);
        return ordinal >= 0 && ordinal < State.values().length ? State.values()[ordinal] : State.IDLE;
    }

    @Override
    public void registerControllers(AnimatableManager.ControllerRegistrar controllers) {
        controllers.add(new AnimationController<>(this, "behavior", 5, this::animation));
    }

    private <E extends ProductionVoidStalkerEntity> PlayState animation(AnimationState<E> animationState) {
        if (isDeadOrDying()) return animationState.setAndContinue(DEATH);
        State visibleState = state();
        if (visibleState == State.HURT) return animationState.setAndContinue(HURT_ANIM);
        if (visibleState == State.ATTACK_PREP || visibleState == State.RECOVER) return animationState.setAndContinue(ATTACK);
        if (visibleState == State.REPOSITION) return animationState.setAndContinue(REPOSITION_ANIM);
        if (visibleState == State.OBSERVE || visibleState == State.AWARE) return animationState.setAndContinue(OBSERVE_ANIM);
        if (animationState.isMoving()) return animationState.setAndContinue(visibleState == State.POSITION || visibleState == State.RETREAT ? RUN : WALK);
        return animationState.setAndContinue(IDLE);
    }

    @Override
    public AnimatableInstanceCache getAnimatableInstanceCache() {
        return animationCache;
    }

    @Override
    public void addAdditionalSaveData(CompoundTag tag) {
        super.addAdditionalSaveData(tag);
        tag.putString("StalkerState", state.name());
        tag.putInt("AttackCooldown", attackCooldown);
        tag.putInt("RepositionCooldown", repositionCooldown);
    }

    @Override
    public void readAdditionalSaveData(CompoundTag tag) {
        super.readAdditionalSaveData(tag);
        try {
            state = State.valueOf(tag.getString("StalkerState"));
        } catch (IllegalArgumentException ignored) {
            state = State.IDLE;
        }
        entityData.set(DATA_STATE, state.ordinal());
        attackCooldown = tag.getInt("AttackCooldown");
        repositionCooldown = tag.getInt("RepositionCooldown");
    }

    public enum State { IDLE, AWARE, OBSERVE, SEARCH, POSITION, ATTACK_PREP, RECOVER, REPOSITION, RETREAT, HURT }
}

package com.infernodude777.endesium.resonance;

import com.infernodude777.endesium.Endesium;
import com.infernodude777.endesium.particle.ModParticles;
import com.infernodude777.endesium.registry.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.Vec3;

import java.util.HashMap;
import java.util.Map;
import java.util.WeakHashMap;

/**
 * Server-side registry of loaded mechanism signals. Signals stay bounded and
 * qualitative: the client never learns exact source positions through the Lens.
 * Band and an eight-way direction bucket are the only information that ever
 * leaves the server.
 */
public final class ResonanceManager {
    private static final Map<ServerLevel, ResonanceManager> INSTANCES = new WeakHashMap<>();
    private static final int MAX_SEARCH_RADIUS = 512;
    private static final String[] CARDINALS = { "east", "southeast", "south", "southwest",
            "west", "northwest", "north", "northeast" };

    private final ServerLevel level;
    private final Map<BlockPos, ResonanceSource> sources = new HashMap<>();

    private ResonanceManager(ServerLevel level) {
        this.level = level;
    }

    public static ResonanceManager get(ServerLevel level) {
        return INSTANCES.computeIfAbsent(level, ResonanceManager::new);
    }

    public void registerSource(BlockPos position, ResonanceType type, int radius, float strength, boolean active) {
        BlockPos key = position.immutable();
        sources.compute(key, (ignored, existing) -> {
            if (existing == null) {
                return new ResonanceSource(key, type, Math.min(radius, MAX_SEARCH_RADIUS), strength, active);
            }
            existing.update(type, Math.min(radius, MAX_SEARCH_RADIUS), strength, active);
            return existing;
        });
    }

    public void unregisterSource(BlockPos position) {
        sources.remove(position);
    }

    /** Samples only sources in this End dimension and returns the strongest visible signal. */
    public Signal sample(ServerPlayer player) {
        if (player.level().dimension() != Level.END) return Signal.none();

        Signal strongest = Signal.none();
        java.util.Iterator<ResonanceSource> iterator = sources.values().iterator();
        while (iterator.hasNext()) {
            ResonanceSource source = iterator.next();
            if (!level.isLoaded(source.position())) {
                iterator.remove();
                continue;
            }
            double distanceSqr = source.position().distSqr(player.blockPosition());
            if (distanceSqr > (double) source.detectionRadius() * source.detectionRadius()) continue;

            double distance = Math.sqrt(distanceSqr);
            float visibility = visibilityFactor(player, source);
            float strength = (float) Math.clamp((source.detectionRadius() - distance) / 96.0D, 0.0D, 1.0D)
                    * source.strength() * visibility;
            strength = Math.clamp(strength, 0.0F, 1.0F);
            Band band = distance <= 16 ? Band.VERY_CLOSE
                    : distance <= 32 ? Band.CLOSE
                    : distance <= 64 ? Band.MEDIUM
                    : Band.FAR;
            Signal candidate = new Signal(band, strength, source.position(), source.active(),
                    directionBucket(player, source.position()), source.type());
            if (candidate.strength() > strongest.strength()) strongest = candidate;
        }
        return strongest;
    }

    private float visibilityFactor(ServerPlayer player, ResonanceSource source) {
        Vec3 from = player.getEyePosition();
        Vec3 to = Vec3.atCenterOf(source.position());
        BlockHitResult hit = level.clip(new ClipContext(from, to, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, player));
        if (hit.getType() == HitResult.Type.BLOCK && hit.getBlockPos().distSqr(source.position()) > 1.0D) {
            return 0.35F;
        }
        return 1.0F;
    }

    public void emitLensFeedback(ServerPlayer player) {
        Signal signal = sample(player);
        if (signal.band() == Band.NONE) {
            player.displayClientMessage(Component.literal("The lens is quiet."), true);
            return;
        }

        player.displayClientMessage(Component.literal(describe(signal)), true);
        boolean strong = signal.band() == Band.VERY_CLOSE;
        Vec3 audioOffset = directionOffset(signal.directionBucket());
        BlockPos audioPos = BlockPos.containing(player.position().add(audioOffset));
        level.playSound(null, audioPos,
                strong ? ModSounds.RESONANCE_LENS_PULSE_HIGH : ModSounds.RESONANCE_LENS_PULSE_LOW,
                SoundSource.PLAYERS, 0.25F + signal.strength() * 0.4F, 0.65F + signal.strength() * 0.4F);
        int count = switch (signal.band()) {
            case FAR -> 1;
            case MEDIUM -> 2;
            case CLOSE -> 3;
            case VERY_CLOSE -> 4;
            case NONE -> 0;
        };
        level.sendParticles(ModParticles.RESONANCE_PULSE, player.getX(), player.getY(0.7D), player.getZ(), count,
                0.25D, 0.25D, 0.25D, 0.01D);
    }

    /** Maps an eight-way direction bucket to a readable cardinal name. */
    public static String cardinal(int bucket) {
        if (bucket < 0 || bucket >= CARDINALS.length) return "the void";
        return CARDINALS[bucket];
    }

    private static String describe(Signal signal) {
        String message = switch (signal.band()) {
            case FAR -> switch (signal.sourceType()) {
                case STRONG_RELIC -> "A strong resonance answers from the wastes.";
                case SPIRE_CORE -> "The lens is almost overwhelmed.";
                case AWAKENED_ARCHIVE -> "A deep resonance answers from beyond the wastes.";
                default -> "The lens is listening.";
            };
            case MEDIUM -> switch (signal.sourceType()) {
                case STRONG_RELIC -> "A strong resonance answers from the wastes.";
                case SPIRE_CORE -> "The lens is almost overwhelmed.";
                case AWAKENED_ARCHIVE -> "A deep resonance answers from beyond the wastes.";
                default -> "A distant resonance answers.";
            };
            case CLOSE -> "The resonance is close.";
            case VERY_CLOSE -> "The lens is answering.";
            case NONE -> "The lens is quiet.";
        };
        if (signal.directionBucket() >= 0 && signal.band() != Band.FAR) {
            message = message + " It pulls toward the " + cardinal(signal.directionBucket()) + ".";
        }
        return message;
    }

    public boolean activate(BlockPos position, ServerPlayer player) {
        if (player.level() != level || player.distanceToSqr(Vec3.atCenterOf(position)) > 16.0D) return false;

        ResonanceSource source = sources.get(position);
        if (source == null) {
            registerSource(position, ResonanceType.ACTIVE_MECHANISM, 96, 1.35F, true);
            source = sources.get(position);
        } else {
            source.update(ResonanceType.ACTIVE_MECHANISM, 96, 1.35F, true);
        }
        level.sendParticles(ModParticles.RESONANCE_ACTIVE, position.getX() + 0.5D, position.getY() + 1.0D,
                position.getZ() + 0.5D, 12, 0.35D, 0.25D, 0.35D, 0.04D);
        level.sendParticles(ModParticles.RUIN_GOLD_CONTACT, position.getX() + 0.5D, position.getY() + 0.5D,
                position.getZ() + 0.5D, 4, 0.25D, 0.15D, 0.25D, 0.02D);
        level.playSound(null, position, ModSounds.RUIN_MECHANISM_ACTIVATE, SoundSource.BLOCKS, 1.0F, 0.7F);
        Endesium.LOGGER.info("Activated Endesium resonance source at {} for {}", position, player.getGameProfile().getName());
        return true;
    }

    private static int directionBucket(ServerPlayer player, BlockPos source) {
        double dx = source.getX() + 0.5D - player.getX();
        double dz = source.getZ() + 0.5D - player.getZ();
        int bucket = (int) Math.floor(Math.atan2(dz, dx) / (Math.PI * 2.0D) * 8.0D + 0.5D);
        return Math.floorMod(bucket, 8);
    }

    private static Vec3 directionOffset(int bucket) {
        if (bucket < 0) return Vec3.ZERO;
        double angle = (bucket / 8.0D) * Math.PI * 2.0D;
        return new Vec3(Math.cos(angle) * 2.0D, 0.0D, Math.sin(angle) * 2.0D);
    }

    public enum Band { NONE, FAR, MEDIUM, CLOSE, VERY_CLOSE }

    public record Signal(Band band, float strength, BlockPos sourcePosition, boolean active,
            int directionBucket, ResonanceType sourceType) {
        public static Signal none() {
            return new Signal(Band.NONE, 0.0F, BlockPos.ZERO, false, -1, ResonanceType.DORMANT_RELIC);
        }
    }
}

package com.infernodude777.endesium.command;

import com.infernodude777.endesium.state.PostDragonEvents;
import com.infernodude777.endesium.state.PostDragonState;
import com.mojang.brigadier.arguments.BoolArgumentType;
import com.mojang.brigadier.arguments.StringArgumentType;
import com.mojang.brigadier.context.CommandContext;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.commands.Commands;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceKey;
import java.util.Locale;
import java.util.Map;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.biome.Biome;
import net.minecraft.world.level.levelgen.structure.Structure;

/**
 * Development-only Endesium commands, all gated to permission level 2.
 * They exist so the post-Dragon state can be exercised headlessly.
 */
public final class EndesiumCommands {
    private EndesiumCommands() { }

    public static void register() {
        CommandRegistrationCallback.EVENT.register((dispatcher, registryAccess, environment) ->
                dispatcher.register(Commands.literal("endesium")
                        .then(Commands.literal("dragonstate")
                                .requires(source -> source.hasPermission(2))
                                .then(Commands.literal("get")
                                        .executes(EndesiumCommands::getDragonState))
                                .then(Commands.literal("set")
                                        .requires(source -> DEV_COMMANDS_ENABLED)
                                        .then(Commands.argument("active", BoolArgumentType.bool())
                                                .executes(ctx -> setDragonState(ctx,
                                                        BoolArgumentType.getBool(ctx, "active"))))))
                        .then(Commands.literal("locate")
                                .then(Commands.literal("biome")
                                        .then(Commands.argument("biome", StringArgumentType.string())
                                                .executes(ctx -> locateBiome(ctx,
                                                        StringArgumentType.getString(ctx, "biome")))))
                                .then(Commands.literal("structure")
                                        .then(Commands.argument("structure", StringArgumentType.string())
                                                .suggests((context, builder) -> {
                                                    for (String name : FLAGSHIP_REGIONS.keySet()) builder.suggest(name);
                                                    for (String name : LANDMARK_NAMES) builder.suggest(name);
                                                    return builder.buildFuture();
                                                })
                                                .executes(ctx -> locateStructure(ctx,
                                                        StringArgumentType.getString(ctx, "structure"))))))));
    }

    private static final boolean DEV_COMMANDS_ENABLED =
            Boolean.getBoolean("endesium.devcommands");

    private static int locateBiome(CommandContext<CommandSourceStack> ctx, String biomeId) throws com.mojang.brigadier.exceptions.CommandSyntaxException {
        ServerLevel level = ctx.getSource().getLevel();
        ResourceLocation id;
        try {
            id = ResourceLocation.parse(biomeId);
        } catch (Exception e) {
            ctx.getSource().sendFailure(Component.literal("Invalid biome id: " + biomeId));
            return 0;
        }
        ResourceKey<Biome> key = ResourceKey.create(Registries.BIOME, id);
        var holderOpt = ctx.getSource().getServer().registryAccess().lookupOrThrow(Registries.BIOME).get(key);
        if (holderOpt.isEmpty()) {
            var tagOpt = ctx.getSource().getServer().registryAccess().lookupOrThrow(Registries.BIOME).get(net.minecraft.tags.TagKey.create(Registries.BIOME, id));
            if (tagOpt.isPresent()) {
                var tag = tagOpt.get();
                BlockPos origin = BlockPos.containing(ctx.getSource().getPosition());
                java.util.function.Predicate<net.minecraft.core.Holder<Biome>> pred = h -> tag.contains(h);
                var found = level.findClosestBiome3d(pred, origin, 6400, 32, 64);
                if (found != null) {
                    BlockPos pos = found.getFirst();
                    String name = found.getSecond().unwrapKey().map(k -> k.location().toString()).orElse(id.toString());
                    double dist = Math.sqrt(ctx.getSource().getPosition().distanceToSqr(pos.getX(), pos.getY(), pos.getZ()));
                    ctx.getSource().sendSuccess(() -> Component.literal("Nearest " + name + " is at [" + pos.getX() + ", " + pos.getY() + ", " + pos.getZ() + "] (" + (int) dist + " blocks)"), false);
                    return 1;
                }
            }
            ctx.getSource().sendFailure(Component.literal("Biome not found: " + biomeId));
            return 0;
        }
        var holder = holderOpt.get();
        BlockPos origin = BlockPos.containing(ctx.getSource().getPosition());
        java.util.function.Predicate<net.minecraft.core.Holder<Biome>> pred = h -> h.is(key);
        var found = level.findClosestBiome3d(pred, origin, 6400, 32, 64);
        if (found != null) {
            BlockPos pos = found.getFirst();
            String name = found.getSecond().unwrapKey().map(k -> k.location().toString()).orElse(id.toString());
            double dist = Math.sqrt(ctx.getSource().getPosition().distanceToSqr(pos.getX(), pos.getY(), pos.getZ()));
            ctx.getSource().sendSuccess(() -> Component.literal("Nearest " + name + " is at [" + pos.getX() + ", " + pos.getY() + ", " + pos.getZ() + "] (" + (int) dist + " blocks)"), false);
            return 1;
        }
        ctx.getSource().sendFailure(Component.literal("Biome not found within search radius."));
        return 0;
    }

    private static final Map<String, Integer> FLAGSHIP_REGIONS = Map.ofEntries(
            Map.entry("dust_cathedral", com.infernodude777.endesium.world.EndesiumRegions.END_WASTES),
            Map.entry("elderwood_sanctum", com.infernodude777.endesium.world.EndesiumRegions.CHORUS_WILDS),
            Map.entry("skyrend_keep", com.infernodude777.endesium.world.EndesiumRegions.SHATTERED_HIGHLANDS),
            Map.entry("drowned_cathedral", com.infernodude777.endesium.world.EndesiumRegions.VOID_MARSHES),
            Map.entry("lumen_cathedral", com.infernodude777.endesium.world.EndesiumRegions.LUMINOUS_GROVES),
            Map.entry("great_caldera", com.infernodude777.endesium.world.EndesiumRegions.ASHEN_EXPANSE),
            Map.entry("volcano", com.infernodude777.endesium.world.EndesiumRegions.ASHEN_EXPANSE),
            Map.entry("sunken_geode", com.infernodude777.endesium.world.EndesiumRegions.CRYSTAL_BARRENS),
            Map.entry("void_spire", com.infernodude777.endesium.world.EndesiumRegions.VOID_SKIRTS),
            Map.entry("crown_observatory", com.infernodude777.endesium.world.EndesiumRegions.VOID_CROWN),
            Map.entry("null_archive", com.infernodude777.endesium.world.EndesiumRegions.UMBRAL_REACH));

    private static final java.util.Set<String> LANDMARK_NAMES = java.util.Set.of(
            "dune_fossil_arch", "hollow_stump", "windvane_watchtower", "mire_bell_cairn",
            "lightwell_gazebo", "ember_shrine", "shard_spire_cluster", "anchor_ruin",
            "needle_circle", "null_obelisk");

    private static int locateLattice(CommandContext<CommandSourceStack> ctx, String name,
            int region, boolean flagship) {
        ServerLevel level = ctx.getSource().getLevel();
        long seed = com.infernodude777.endesium.world.EndesiumWorldgenSeeds.get();
        BlockPos origin = BlockPos.containing(ctx.getSource().getPosition());
        int grid = flagship
                ? com.infernodude777.endesium.world.BiomeStructureFeature.SPACING_GRID
                : com.infernodude777.endesium.world.RegionLandmarkFeature.SPACING_GRID;
        int playerCellX = Math.floorDiv(origin.getX() >> 4, grid);
        int playerCellZ = Math.floorDiv(origin.getZ() >> 4, grid);

        long bestDistSq = Long.MAX_VALUE;
        int[] bestChunk = null;
        for (int ring = 0; bestChunk == null || ring <= 6; ring++) {
            if (ring > 12) break;
            for (int dx = -ring; dx <= ring; dx++) {
                for (int dz = -ring; dz <= ring; dz++) {
                    if (Math.max(Math.abs(dx), Math.abs(dz)) != ring) continue;
                    int[] chunk = flagship
                            ? com.infernodude777.endesium.world.BiomeStructureFeature
                                    .flagshipChunk(seed, region, playerCellX + dx, playerCellZ + dz)
                            : com.infernodude777.endesium.world.RegionLandmarkFeature
                                    .landmarkChunk(seed, region, playerCellX + dx, playerCellZ + dz);
                    int wx = chunk[0] * 16 + 8;
                    int wz = chunk[1] * 16 + 8;
                    long distSq = (long) (wx - origin.getX()) * (wx - origin.getX())
                            + (long) (wz - origin.getZ()) * (wz - origin.getZ());
                    if (distSq < bestDistSq) {
                        bestDistSq = distSq;
                        bestChunk = chunk;
                    }
                }
            }
        }
        if (bestChunk == null) {
            ctx.getSource().sendFailure(Component.literal("No anchor found nearby."));
            return 0;
        }
        int wx = bestChunk[0] * 16 + 8;
        int wz = bestChunk[1] * 16 + 8;
        int dist = (int) Math.sqrt(bestDistSq);
        String label = name.toLowerCase(Locale.ROOT).replace('_', ' ');
        ctx.getSource().sendSuccess(() -> Component.literal(
                "Nearest " + label + " anchor is near [" + wx + ", ~70, " + wz + "] (" + dist
                        + " blocks). The structure generates when its chunk loads."),
                false);
        return 1;
    }

    private static int locateStructure(CommandContext<CommandSourceStack> ctx, String structureId) {
        String bare = structureId.toLowerCase(Locale.ROOT).trim();
        if (bare.startsWith("endesium:")) bare = bare.substring("endesium:".length());
        if (bare.contains(" ")) bare = bare.replace(' ', '_');
        if (FLAGSHIP_REGIONS.containsKey(bare)) return locateLattice(ctx, bare, FLAGSHIP_REGIONS.get(bare), true);
        if (LANDMARK_NAMES.contains(bare)) {
            int region = landmarkRegionFor(bare);
            return locateLattice(ctx, bare, region, false);
        }

        ServerLevel level = ctx.getSource().getLevel();
        ResourceLocation id;
        try {
            id = ResourceLocation.parse(structureId);
        } catch (Exception e) {
            ctx.getSource().sendFailure(Component.literal("Invalid structure id: " + structureId));
            return 0;
        }
        ResourceKey<Structure> key = ResourceKey.create(Registries.STRUCTURE, id);
        var holderOpt = ctx.getSource().getServer().registryAccess().lookupOrThrow(Registries.STRUCTURE).get(key);
        if (holderOpt.isEmpty()) {
            var tagOpt = ctx.getSource().getServer().registryAccess().lookupOrThrow(Registries.STRUCTURE).get(net.minecraft.tags.TagKey.create(Registries.STRUCTURE, id));
            if (tagOpt.isPresent()) {
                var found = level.getChunkSource().getGenerator().findNearestMapStructure(level, tagOpt.get(), BlockPos.containing(ctx.getSource().getPosition()), 100, false);
                if (found != null) {
                    BlockPos pos = new BlockPos(found.getFirst().getX(), found.getFirst().getY(), found.getFirst().getZ());
                    String name = found.getSecond().unwrapKey().map(k -> k.location().toString()).orElse(id.toString());
                    double dist = Math.sqrt(ctx.getSource().getPosition().distanceToSqr(pos.getX(), pos.getY(), pos.getZ()));
                    ctx.getSource().sendSuccess(() -> Component.literal("Nearest " + name + " is at [" + pos.getX() + ", " + pos.getY() + ", " + pos.getZ() + "] (" + (int) dist + " blocks)"), false);
                    return 1;
                }
            }
            ctx.getSource().sendFailure(Component.literal(
                    "Structure not found: " + structureId + ". Endesium flagships: dust_cathedral, elderwood_sanctum, "
                            + "skyrend_keep, drowned_cathedral, lumen_cathedral, great_caldera, sunken_geode, void_spire, "
                            + "crown_observatory, null_archive."));
            return 0;
        }
        var holder = holderOpt.get();
        var found = level.getChunkSource().getGenerator().findNearestMapStructure(level, net.minecraft.core.HolderSet.direct(holder), BlockPos.containing(ctx.getSource().getPosition()), 100, false);
        if (found != null) {
            BlockPos pos = new BlockPos(found.getFirst().getX(), found.getFirst().getY(), found.getFirst().getZ());
            String name = found.getSecond().unwrapKey().map(k -> k.location().toString()).orElse(id.toString());
            double dist = Math.sqrt(ctx.getSource().getPosition().distanceToSqr(pos.getX(), pos.getY(), pos.getZ()));
            ctx.getSource().sendSuccess(() -> Component.literal("Nearest " + name + " is at [" + pos.getX() + ", " + pos.getY() + ", " + pos.getZ() + "] (" + (int) dist + " blocks)"), false);
            return 1;
        }
        ctx.getSource().sendFailure(Component.literal(
                "Structure not found within search radius. Endesium flagships: dust_cathedral, elderwood_sanctum, "
                        + "skyrend_keep, drowned_cathedral, lumen_cathedral, great_caldera, sunken_geode, void_spire, "
                        + "crown_observatory, null_archive."));
        return 0;
    }

    private static int landmarkRegionFor(String name) {
        return switch (name) {
            case "dune_fossil_arch" -> com.infernodude777.endesium.world.EndesiumRegions.END_WASTES;
            case "hollow_stump" -> com.infernodude777.endesium.world.EndesiumRegions.CHORUS_WILDS;
            case "windvane_watchtower" -> com.infernodude777.endesium.world.EndesiumRegions.SHATTERED_HIGHLANDS;
            case "mire_bell_cairn" -> com.infernodude777.endesium.world.EndesiumRegions.VOID_MARSHES;
            case "lightwell_gazebo" -> com.infernodude777.endesium.world.EndesiumRegions.LUMINOUS_GROVES;
            case "ember_shrine" -> com.infernodude777.endesium.world.EndesiumRegions.ASHEN_EXPANSE;
            case "shard_spire_cluster" -> com.infernodude777.endesium.world.EndesiumRegions.CRYSTAL_BARRENS;
            case "anchor_ruin" -> com.infernodude777.endesium.world.EndesiumRegions.VOID_SKIRTS;
            case "needle_circle" -> com.infernodude777.endesium.world.EndesiumRegions.VOID_CROWN;
            default -> com.infernodude777.endesium.world.EndesiumRegions.UMBRAL_REACH;
        };
    }

    private static int getDragonState(CommandContext<CommandSourceStack> ctx) {
        PostDragonState state = PostDragonState.get(ctx.getSource().getServer());
        ctx.getSource().sendSuccess(() -> Component.literal(
                "Endesium post-Dragon state: transformation=" + state.isTransformationActive()
                        + ", dragon defeated=" + state.isDragonDefeated()
                        + ", version=" + state.transformationVersion()), true);
        return 1;
    }

    private static int setDragonState(CommandContext<CommandSourceStack> ctx, boolean active) {
        PostDragonState state = PostDragonState.get(ctx.getSource().getServer());
        if (active) {
            if (state.markDragonDefeated()) {
                ServerLevel end = ctx.getSource().getServer().getLevel(Level.END);
                if (end != null) PostDragonEvents.fireTransformation(end, new BlockPos(0, 70, 0));
                ctx.getSource().sendSuccess(() -> Component.literal(
                        "Endesium post-Dragon transformation activated (development command)."), true);
            } else {
                ctx.getSource().sendSuccess(() -> Component.literal(
                        "Endesium post-Dragon transformation is already active."), true);
            }
        } else {
            state.resetForTesting();
            ctx.getSource().sendSuccess(() -> Component.literal(
                    "Endesium post-Dragon state reset (development command)."), true);
        }
        return 1;
    }
}

package com.infernodude777.endesium.gear;

import com.infernodude777.endesium.registry.ModEndgear;
import com.infernodude777.endesium.registry.ModItems;
import net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;

/**
 * Cross-set synergies for the non-void gear lines. Wearing a FULL set while
 * holding that line's tool merges armor and weapon into one fighting system —
 * a drastic deepening of the Luminous / Ash / Null identity beyond the
 * per-piece passives handled in {@link GearAbilities}.
 *
 * <p>Each line grants one lingering passive while its tools are held in the
 * full set, plus a burst rider on every hit with a matching tool.
 * <ul>
 *   <li><b>Luminous</b> (full set + any Luminous tool): Prism Grip — Speed II
 *       and Haste II; hits blind with a flash (3 true damage + Glowing) and
 *       spark light shards.</li>
 *   <li><b>Ash</b> (full set incl. Ashwalker boots + any Ash tool): Ember
 *       Core — Fire Resistance while channelling; hits stoke the burn for 2
 *       extra seconds and knock the foe back.</li>
 *   <li><b>Null</b> (full set + any Null tool): Erased Edge — Strength I and
 *       Haste I; every hit shreds 4 armor durability and drags the foe in.</li>
 * </ul>
 *
 * <p>Self-registering: building this object hooks the tick + hurt events, so
 * exactly instantiating it (see the loader in {@code GearAbilities}) activates
 * the layer with the rest of the gear system.
 */
public final class EndgearSetBonuses {

    public EndgearSetBonuses() {
        ServerTickEvents.END_SERVER_TICK.register(EndgearSetBonuses::tick);
        ServerLivingEntityEvents.AFTER_DAMAGE.register(EndgearSetBonuses::onHurt);
    }

    private static void tick(MinecraftServer server) {
        for (ServerPlayer player : server.getPlayerList().getPlayers()) {
            applyPassives(player);
        }
    }

    // ---------------------------------------------------------------
    // Passive lingering bonuses while a matched tool is held in the set
    // ---------------------------------------------------------------
    private static void applyPassives(ServerPlayer player) {
        ItemStack main = player.getMainHandItem();

        if (isFullLuminous(player) && isLuminousTool(main)) {
            // Prism Grip: blazing speed + dig rate for the whole toolkit.
            player.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 40, 1, false, false, true));
            player.addEffect(new MobEffectInstance(MobEffects.DIG_SPEED, 40, 1, false, false, true));
        }

        if (isFullAsh(player) && isAshTool(main)) {
            // Ember Core: heat-immunity while channelling fire.
            player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 40, 0, false, false, true));
        }

        if (isFullNull(player) && isNullTool(main)) {
            // Erased Edge: heavier, faster strikes.
            player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 40, 0, false, false, true));
            player.addEffect(new MobEffectInstance(MobEffects.DIG_SPEED, 40, 0, false, false, true));
        }
    }

    // ---------------------------------------------------------------
    // Hit riders: an extra kick every time a matched tool lands
    // ---------------------------------------------------------------
    private static void onHurt(LivingEntity target, DamageSource source,
            float sourceDamage, float currentDamage, boolean blocked) {
        if (!(target.level() instanceof ServerLevel level)) return;
        Entity attackerEntity = source.getEntity();
        if (!(attackerEntity instanceof ServerPlayer player)) return;
        ItemStack main = player.getMainHandItem();

        if (isFullLuminous(player) && isLuminousTool(main)) {
            // Radiant kick: a flash that adds true damage and lights the foe.
            if (!target.hasEffect(MobEffects.GLOWING)) {
                target.addEffect(new MobEffectInstance(MobEffects.GLOWING, 80, 0, false, false, true));
                target.hurt(player.damageSources().magic(), 3.0F);
                level.sendParticles(ParticleTypes.FLASH,
                        target.getX(), target.getY() + 0.8D, target.getZ(),
                        1, 0.0D, 0.0D, 0.0D, 0.0D);
            }
            level.sendParticles(ParticleTypes.END_ROD,
                    target.getX(), target.getY() + 0.8D, target.getZ(),
                    6, 0.3D, 0.3D, 0.3D, 0.04D);
        }

        if (isFullAsh(player) && isAshTool(main)) {
            // Stoked flame: the burn lingers and throws weight behind the hit.
            target.igniteForSeconds(2);
            Vec3 kb = target.position().subtract(player.position()).normalize();
            target.setDeltaMovement(target.getDeltaMovement().add(kb.x * 0.4D, 0.22D, kb.z * 0.4D));
            target.hurtMarked = true;
            level.sendParticles(ParticleTypes.FLAME,
                    target.getX(), target.getY() + 0.8D, target.getZ(),
                    7, 0.3D, 0.3D, 0.3D, 0.05D);
        }

        if (isFullNull(player) && isNullTool(main)) {
            // Deleted durability and a gentle pull into the blade.
            shredArmor(target);
            Vec3 pull = player.position().subtract(target.position()).normalize();
            target.setDeltaMovement(target.getDeltaMovement().add(pull.x * 0.4D, 0.02D, pull.z * 0.4D));
            target.hurtMarked = true;
            level.sendParticles(ParticleTypes.PORTAL,
                    target.getX(), target.getY() + 0.8D, target.getZ(),
                    5, 0.25D, 0.3D, 0.25D, 0.04D);
        }
    }

    private static void shredArmor(LivingEntity target) {
        for (EquipmentSlot slot : new EquipmentSlot[]{EquipmentSlot.HEAD, EquipmentSlot.CHEST,
                EquipmentSlot.LEGS, EquipmentSlot.FEET}) {
            ItemStack worn = target.getItemBySlot(slot);
            if (!worn.isEmpty() && worn.isDamageableItem()) {
                worn.setDamageValue(worn.getDamageValue() + 4);
            }
        }
    }

    // ---------------------------------------------------------------
    // Set / tool membership checks
    // ---------------------------------------------------------------
    private static boolean isFullLuminous(ServerPlayer p) {
        return p.getItemBySlot(EquipmentSlot.HEAD).is(ModEndgear.LUMINOUS_HELMET)
                && p.getItemBySlot(EquipmentSlot.CHEST).is(ModEndgear.LUMINOUS_CHESTPLATE)
                && p.getItemBySlot(EquipmentSlot.LEGS).is(ModEndgear.LUMINOUS_LEGGINGS)
                && p.getItemBySlot(EquipmentSlot.FEET).is(ModEndgear.LUMINOUS_BOOTS);
    }

    private static boolean isFullAsh(ServerPlayer p) {
        return p.getItemBySlot(EquipmentSlot.HEAD).is(ModEndgear.ASH_HELMET)
                && p.getItemBySlot(EquipmentSlot.CHEST).is(ModEndgear.ASH_CHESTPLATE)
                && p.getItemBySlot(EquipmentSlot.LEGS).is(ModEndgear.ASH_LEGGINGS)
                && p.getItemBySlot(EquipmentSlot.FEET).is(ModItems.ASHWALKER_BOOTS);
    }

    private static boolean isFullNull(ServerPlayer p) {
        return p.getItemBySlot(EquipmentSlot.HEAD).is(ModEndgear.NULL_HELMET)
                && p.getItemBySlot(EquipmentSlot.CHEST).is(ModEndgear.NULL_CHESTPLATE)
                && p.getItemBySlot(EquipmentSlot.LEGS).is(ModEndgear.NULL_LEGGINGS)
                && p.getItemBySlot(EquipmentSlot.FEET).is(ModEndgear.NULL_BOOTS);
    }

    private static boolean isLuminousTool(ItemStack s) {
        return s.is(ModEndgear.LUMINOUS_SWORD) || s.is(ModEndgear.LUMINOUS_PICKAXE)
                || s.is(ModEndgear.LUMINOUS_AXE) || s.is(ModEndgear.LUMINOUS_SHOVEL)
                || s.is(ModEndgear.LUMINOUS_HOE);
    }

    private static boolean isAshTool(ItemStack s) {
        return s.is(ModEndgear.ASH_SWORD) || s.is(ModEndgear.ASH_PICKAXE)
                || s.is(ModEndgear.ASH_AXE) || s.is(ModEndgear.ASH_SHOVEL)
                || s.is(ModEndgear.ASH_HOE);
    }

    private static boolean isNullTool(ItemStack s) {
        return s.is(ModEndgear.NULL_SWORD) || s.is(ModEndgear.NULL_PICKAXE)
                || s.is(ModEndgear.NULL_AXE) || s.is(ModEndgear.NULL_SHOVEL)
                || s.is(ModEndgear.NULL_HOE);
    }
}

package com.infernodude777.endesium.command;

